moves = {
    root / 'docs/decisions/PRODUCTION_DECISIONS.md': root / 'production/DESIGN_DECISIONS.md',
    root / 'V1_SCOPE.md': root / 'production/V1_SCOPE.md',
    root / 'SLACK_GATEWAY_PRD.md': root / 'production/SLACK_GATEWAY_PRD.md',
}
for source, destination in moves.items():
    if not source.is_file() or destination.exists():
        raise SystemExit(f'Refusing unexpected move: {source} -> {destination}')

link_pattern = re.compile(r'(\[[^\]]*\]\()([^\n)]+)(\))')
updates = {}
for source in root.rglob('*.md'):
    relative = source.relative_to(root)
    if any(part in {'.git', '.local', 'hermes', 'node_modules', '__pycache__'} for part in relative.parts):
        continue
    original = source.read_text()
    destination = moves.get(source, source)
    def rewrite(match):
        target = match.group(2)
        if re.match(r'^[a-zA-Z][a-zA-Z0-9+.-]*:', target) or target.startswith('/'):
            return match.group(0)
        path_part, marker, anchor = target.partition('#')
        if not path_part:
            return match.group(0)
        old_target = (source.parent / path_part).resolve()
        new_target = moves.get(old_target, old_target)
        if destination == source and new_target == old_target:
            return match.group(0)
        new_relative = os.path.relpath(new_target, destination.parent)
        return match.group(1) + new_relative + (marker + anchor if marker else '') + match.group(3)
    rewritten = link_pattern.sub(rewrite, original)
    if rewritten != original or destination != source:
        updates[source] = (destination, rewritten)

(root / 'production').mkdir(exist_ok=True)
for source, (destination, content) in updates.items():
    if source in moves:
        source.rename(destination)
    destination.write_text(content)
print('Moved three production design documents; updated local links in', len(updates), 'documents.')
for source, destination in moves.items():
